load exampleMaps.mat
map = occupancyMap(simpleMap, 10);
ss = stateSpaceSE2;
ss.StateBounds = [map.XWorldLimits; map.YWorldLimits; [-pi pi]];
sv = validatorOccupancyMap(ss, 'Map', map, 'ValidationDistance', 0.05);
planner = plannerRRTStar(ss, sv, 'MaxConnectionDistance', 1, ...
    'MaxIterations', 5000, 'ContinueAfterGoalReached', true);
rng(1);
[pthObj, solnInfo] = plan(planner, [2 2 0], [20 12 0]);
show(map); hold on
plot(pthObj.States(:,1), pthObj.States(:,2), 'r-', 'LineWidth', 2);

path = [0 0; 2 2; 4 2; 6 4; 8 4];
controller = controllerPurePursuit('Waypoints', path, ...
    'LookaheadDistance', 0.6, 'DesiredLinearVelocity', 0.5, ...
    'MaxAngularVelocity', 1.5);
pose = [0 0 0]';
dt = 0.1;
for k = 1:400
    [v, w] = controller(pose);
    pose = pose + [v*cos(pose(3)); v*sin(pose(3)); w] * dt;
    if norm(pose(1:2) - path(end,:)') < 0.2, break; end
end
fprintf('Reached (%.2f, %.2f) in %d steps\n', pose(1), pose(2), k);

fs = 100;
fuse = imufilter('SampleRate', fs, 'GyroscopeNoise', 1e-5);
ld = load('rpy_9axis.mat');
acc = ld.sensorData.Acceleration;
gyro = ld.sensorData.AngularVelocity;
q = fuse(acc, gyro);
eul = eulerd(q, 'ZYX', 'frame');
plot((0:size(eul,1)-1)/fs, eul)
legend('yaw','pitch','roll'); ylabel('degrees')

fs = 100;
fuse = ahrsfilter('SampleRate', fs, 'MagneticFieldStrength', 48);
ld = load('rpy_9axis.mat');
q = fuse(ld.sensorData.Acceleration, ld.sensorData.AngularVelocity, ...
    ld.sensorData.MagneticField);
eul = eulerd(q, 'ZYX', 'frame');
plot((0:size(eul,1)-1)/fs, eul)
legend('yaw','pitch','roll')

fs = 100;
filt = insfilterMARG('IMUSampleRate', fs, ...
    'ReferenceLocation', [42.36 -71.06 10]);
Rpos = 1.0; Rvel = 0.1; Rmag = 0.5;
for k = 1:1000
    predict(filt, accel(k,:), gyro(k,:));
    if mod(k, 10) == 0
        fusegps(filt, gpsPos(k/10,:), Rpos, gpsVel(k/10,:), Rvel);
        fusemag(filt, mag(k,:), Rmag);
    end
end
[p, q, v] = pose(filt);
fprintf('Position: [%.2f %.2f %.2f] m\n', p);

